#include "UserAccount.h"
namespace vox {juce::String roleName(Role r){const char*names[]{"Usuário","Moderador","Administrador","Superadministrador"};return juce::String::fromUTF8(names[(int)r]);}juce::String statusName(UserStatus s){const char*names[]{"Ativo","Inativo","Bloqueado","Pendente"};return juce::String::fromUTF8(names[(int)s]);}juce::var UserAccount::toJson()const{auto*o=new juce::DynamicObject();o->setProperty("id",id);o->setProperty("name",name);o->setProperty("email",email);o->setProperty("windowsIdentity",windowsIdentity);o->setProperty("role",(int)role);o->setProperty("status",(int)status);o->setProperty("created",created.toISO8601(true));o->setProperty("lastAccess",lastAccess.toISO8601(true));return juce::var(o);}UserAccount UserAccount::fromJson(const juce::var&v){UserAccount u;if(auto*o=v.getDynamicObject()){u.id=o->getProperty("id").toString();u.name=o->getProperty("name").toString();u.email=o->getProperty("email").toString();u.windowsIdentity=o->getProperty("windowsIdentity").toString();u.role=(Role)juce::jlimit(0,3,(int)o->getProperty("role"));u.status=(UserStatus)juce::jlimit(0,3,(int)o->getProperty("status"));u.created=juce::Time::fromISO8601(o->getProperty("created").toString());u.lastAccess=juce::Time::fromISO8601(o->getProperty("lastAccess").toString());}return u;}}
